 export async function fetchItems() {
@@ -13,8 +14,22 @@ export async function fetchItems() {

 /** Adds or replaces an item by id. */
 export async function saveItem(item) {
+  highestId = Math.max(highestId, item.id);
   const i = shelf.findIndex((s) => s.id === item.id);
   if (i < 0) shelf.push(item);
   else shelf[i] = item;
   return item;
 }
+
+/** Returns the next unused item id. */
+export function nextItemId() {
+  return ++highestId;
+}
+
+/** Removes an item from the shelf when present. */
+export async function deleteItem(id) {
+  const i = shelf.findIndex((s) => s.id === id);
+  if (i < 0) return false;
+  shelf.splice(i, 1);
+  return true;
+}
